T = np.array([[float(v) for v in r.split(",")] for r in TS.split(";")])
MU = np.array([float(v) for v in MS.split(",")])

def model(x, iv):
    i = x[:, 0].astype(int)
    j = x[:, 1].astype(int)
    ci = iv("code_i", T[i])
    cj = iv("code_j", T[j])
    mid = iv("mid", ci + cj)
    h = iv("mlp", mid)
    post = iv("resid", h)
    logits = np.tile(MU, (x.shape[0], 1))
    logits[:, CLS] += post
    return logits

